recipes.code:
{
  "inputs": [
    {
      "id": "wcagc-mcp-key",
      "type": "promptString",
      "description": "A wcagc API key with the mcp:scan scope. Mint one under Settings -> API keys; every plan can, with a daily quota on Free and Starter.",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@wcagc/mcp@0.7.2"
      ],
      "env": {
        "WCAGC_MCP_KEY": "${input:wcagc-mcp-key}",
        "WCAGC_API_BASE_URL": "<wcagc-api-base-url>"
      }
    }
  }
}
